async (page) => {
  const out = {};
  await page.goto('https://demo.playwright.dev/todomvc/#/bogus');
  out.bogus = await page.evaluate(() => ({
    items: document.querySelectorAll('[data-testid=todo-item]').length,
    selected: [...document.querySelectorAll('.filters a.selected')].map(a=>a.textContent),
    main: !!document.querySelector('.main'),
  }));
  await page.goto('https://demo.playwright.dev/todomvc/#/');
  await page.getByRole('link', { name: 'Completed' }).click();
  await page.getByRole('link', { name: 'Active' }).click();
  await page.goBack();
  out.afterBack = await page.evaluate(() => ({ hash: location.hash, selected: [...document.querySelectorAll('.filters a.selected')].map(a=>a.textContent), items: document.querySelectorAll('[data-testid=todo-item]').length }));
  await page.goForward();
  out.afterForward = await page.evaluate(() => ({ hash: location.hash, selected: [...document.querySelectorAll('.filters a.selected')].map(a=>a.textContent), items: document.querySelectorAll('[data-testid=todo-item]').length }));
  return out;
}

