async (page) => {
  const out = {};
  const seed = async (todos) => {
    await page.goto('https://demo.playwright.dev/todomvc/');
    await page.evaluate((t) => localStorage.setItem('react-todos', JSON.stringify(t)), todos);
    await page.reload();
  };
  await seed([{id:'a',title:'alpha',completed:true},{id:'b',title:'beta',completed:true}]);
  await page.locator('label[for=toggle-all]').click();
  out.untoggleAll = await page.evaluate(() => ({
    completed: [...document.querySelectorAll('[data-testid=todo-item]')].map(e=>e.className),
    count: document.querySelector('[data-testid=todo-count]').textContent,
    clear: !!document.querySelector('.clear-completed'),
  }));

  // clear completed while on the Completed filter, all completed -> empty state
  await seed([{id:'a',title:'alpha',completed:true},{id:'b',title:'beta',completed:true}]);
  await page.goto('https://demo.playwright.dev/todomvc/#/completed');
  await page.getByRole('button', { name: 'Clear completed' }).click();
  out.clearedOnCompletedFilter = await page.evaluate(() => ({
    hash: location.hash,
    main: !!document.querySelector('.main'),
    footer: !!document.querySelector('.footer'),
    storage: localStorage.getItem('react-todos'),
  }));

  // edit a completed todo keeps it completed
  await seed([{id:'a',title:'alpha',completed:true}]);
  const item = page.getByTestId('todo-item').first();
  await item.getByTestId('todo-title').dblclick();
  await item.getByRole('textbox', { name: 'Edit' }).fill('alpha edited');
  await item.getByRole('textbox', { name: 'Edit' }).press('Enter');
  out.editCompleted = await page.evaluate(() => ({
    classes: [...document.querySelectorAll('[data-testid=todo-item]')].map(e=>e.className),
    titles: [...document.querySelectorAll('[data-testid=todo-title]')].map(e=>e.textContent),
    toggles: [...document.querySelectorAll('input.toggle')].map(e=>e.checked),
    count: document.querySelector('[data-testid=todo-count]').textContent,
  }));
  return out;
}

