  const toggleAll = page.getByLabel('Mark all as complete');
  out.toggleAllVisible = await toggleAll.isVisible();
  out.box = await toggleAll.boundingBox();
  try {
    await toggleAll.check({ timeout: 3000 });
    out.checkWorked = true;
  } catch (e) { out.checkWorked = String(e).slice(0, 200); }
  out.afterCheck = await page.evaluate(() => [...document.querySelectorAll('input.toggle')].map(e=>e.checked));

  // blur-commit via locator.blur()
  const item = page.getByTestId('todo-item').filter({ hasText: 'alpha' });
  await item.getByTestId('todo-title').dblclick();
  const editor = item.getByRole('textbox', { name: 'Edit' });
  await editor.fill('alpha renamed');
  await editor.blur();
  out.titlesAfterBlur = await page.getByTestId('todo-title').allTextContents();
  return out;
}

